SELECT 'EQUIPMENT_CLASS' AS owner_kind, class_id AS owner_id, prop_key, COALESCE(prop_value, '') AS prop_value, COALESCE(uom, '') AS uom FROM emc_equipment_class_property WHERE (UPPER(TRIM(?)) = '' OR UPPER(TRIM(?)) = 'EQUIPMENT_CLASS') AND COALESCE(NULLIF(TRIM(?), ''), class_id) = class_id UNION ALL SELECT 'PERSONNEL_CLASS', class_id, prop_key, COALESCE(prop_value, ''), COALESCE(uom, '') FROM emc_personnel_class_property WHERE (UPPER(TRIM(?)) = '' OR UPPER(TRIM(?)) = 'PERSONNEL_CLASS') AND COALESCE(NULLIF(TRIM(?), ''), class_id) = class_id UNION ALL SELECT 'MATERIAL_CLASS', class_id, prop_key, COALESCE(prop_value, ''), COALESCE(uom, '') FROM emc_material_class_property WHERE (UPPER(TRIM(?)) = '' OR UPPER(TRIM(?)) = 'MATERIAL_CLASS') AND COALESCE(NULLIF(TRIM(?), ''), class_id) = class_id UNION ALL SELECT 'MATERIAL_DEFINITION', definition_id, prop_key, COALESCE(prop_value, ''), COALESCE(uom, '') FROM emc_material_definition_property WHERE (UPPER(TRIM(?)) = '' OR UPPER(TRIM(?)) = 'MATERIAL_DEFINITION') AND COALESCE(NULLIF(TRIM(?), ''), definition_id) = definition_id UNION ALL SELECT 'PERSON', person_id, prop_key, COALESCE(prop_value, ''), COALESCE(uom, '') FROM emc_person_property WHERE (UPPER(TRIM(?)) = '' OR UPPER(TRIM(?)) = 'PERSON') AND COALESCE(NULLIF(TRIM(?), ''), person_id) = person_id
